function tc(meta, fn) {
  const c = { status: 'Not run', ...meta };
  try { const r = fn(); c.actual = r.actual; c.status = r.pass ? 'Pass' : 'Fail'; }
  catch (e) { c.actual = 'Error: ' + e.message; c.status = meta.expectThrow ? 'Pass' : 'Fail'; }
  delete c.expectThrow; cases.push(c); n++;
}
// A negative case: the call must be refused with a message
