const accepts = (fn, check = () => true) => () => { const r = fn(); const ok = check(r); return { actual: ok ? 'Saved' + (r?.id ? ' (' + r.id + ')' : '') : 'Saved, but stored value wrong: ' + JSON.stringify(r).slice(0, 120), pass: ok }; };
