// Client school converted from a Starter proposal (Little Steps): add-on-only features follow what was sold
{
  const db = fresh(); const t = db.tenants.find((x) => x.id === 'TC1'); const p = db.provider.proposals.find((x) => x.clientId === 'TC1' || x.projectId) || db.provider.proposals.find((x) => x.options.client?.startsWith('Little'));
  const act = activeAddons(RC, p.options);
  for (const [addon, label, menus, fns] of ADDON_ONLY) {
    const want = act.includes(addon);
    tc({ id: `CLIENT-TC1-${label.replace(/\W+/g, '').slice(0, 14)}`, suite: 'Tier & add-on', module: label, menu: label, feature: label, tier: p.options.tier === 'STARTER' ? 'Starter' : p.options.tier, addon, role: 'Admin', type: want ? 'Positive' : 'Negative', category: 'UI visibility by add-on',
      title: `Client school Little Steps: ${label} ${want ? 'sold → visible' : 'not sold → hidden'}`, steps: 'Open the converted client school as Admin', expected: want ? 'Visible' : 'Hidden' },
    () => { const m = menus.map((c) => shows(t, c)); const f = fns.map((c) => funcOn(t, c)); const v = [...m, ...f]; return { actual: [...menus.map((c, i) => `${LABEL[c]}:${m[i] ? 'on' : 'off'}`), ...fns.map((c, i) => `${c}:${f[i] ? 'on' : 'off'}`)].join(', '), pass: want ? v.every(Boolean) : !v.some(Boolean) }; });
  }
}

