V({ id: 'STU_ADMISSIONS-01', module: 'Students', menu: 'Admissions & Enquiries', feature: 'New enquiry', role: 'Front Office', type: 'Positive', category: 'Add/Save/Retrieve', title: 'Save an enquiry with an email → acknowledgement emailed', steps: 'Valid enquiry with email', expected: 'APP-2027-#### created; email in outbox' }, () => { const d = db0(); const e = addEnquiry(d, { first: 'Anu', parent: 'Ravi', mobile: '9845012345', email: 'ravi@example.com', grade: 2 }, 'QA'); return { actual: `${e.no}; outbox ${d.outbox[0].to}`, pass: /^APP-2027-\d{4}$/.test(e.no) && d.outbox[0].to === 'ravi@example.com' }; });
