V({ id: 'STU_ADMIT-01', module: 'Students', menu: 'New Admission', feature: 'Admit student', role: 'Front Office', type: 'Positive', category: 'Add/Save/Retrieve', title: 'Admit a student → admission number and guardian created', steps: 'Valid admission', expected: 'Number + surname initial + year, e.g. 0042R2026 (≤ 10 characters); listed in All Students' }, () => { const d = db0(); const s = admitStudent(d, { first: 'Kiran', last: 'Rao', gender: 'Male', dob: '2018-04-04', sectionId: 'C1A', guardianName: 'Rao', relation: 'Father', mobile: '9845012399', email: '', band: 0, house: 'Red' }, 'QA'); return { actual: `${s.admNo}; found ${!!d.students.find((x) => x.admNo === s.admNo)}`, pass: /^\d{4}R2026$/.test(s.admNo) }; });
