V({ id: 'STU_ADMIT-04', module: 'Students', menu: 'New Admission', feature: 'Admission number', role: 'Front Office', type: 'Negative', category: 'Duplicate', title: 'Admission numbers stay unique after a student leaves', steps: 'Remove a student record, then admit two', expected: 'No admission number is reused' }, () => { const d = db0(); const s1 = admitStudent(d, { first: 'Asha', dob: '2019-01-01', sectionId: 'C1A', guardianName: 'Gopal', mobile: '9845012301' }, 'QA'); d.students.splice(d.students.indexOf(d.students.find((x) => x.id !== s1.id)), 1); const s2 = admitStudent(d, { first: 'Bala', dob: '2019-01-01', sectionId: 'C1A', guardianName: 'Gopal', mobile: '9845012302' }, 'QA'); const dup = d.students.filter((x) => x.admNo === s2.admNo).length > 1 || s1.admNo === s2.admNo || d.students.filter((x) => x.id === s2.id).length > 1; return { actual: `${s1.admNo}, ${s2.admNo}${dup ? ' — clash' : ''}`, pass: !dup }; });
