V({ id: 'FEE_COLLECT-01', module: 'Fees', menu: 'Collect Fee', feature: 'Record payment', role: 'Accountant', type: 'Positive', category: 'Add/Save/Retrieve', title: 'Collect ₹5,000 by UPI → receipt', steps: 'Student with dues; ₹5,000 UPI', expected: 'Receipt R-2026-#####; allocated to oldest invoice' }, () => { const d = db0(); const inv = d.invoices.find((i) => i.status !== 'PAID'); const p = recordPayment(d, { studentId: inv.studentId, amount: 5000, mode: 'UPI', ref: 'UPI123', by: 'QA' }); return { actual: `${p.receiptNo}, ${p.allocations.length} allocation(s)`, pass: /^R-2026-\d{5}$/.test(p.receiptNo) && p.allocations.length > 0 }; });
