  V({ id: 'SELF_LEAVE-01', module: 'My Space', menu: 'My Leave', feature: 'Apply leave', role: 'Teacher', type: 'Positive', category: 'Add/Save/Retrieve', title: 'Apply one day of casual leave 10 days ahead', steps: 'CL, today+10', expected: 'Accepted; approvers told' }, () => { const e = L({}); return { actual: e || 'Accepted', pass: !e || /holiday/.test(e) }; });
  V({ id: 'SELF_LEAVE-02', module: 'My Space', menu: 'My Leave', feature: 'Apply leave', role: 'Teacher', type: 'Negative', category: 'Boundary', title: 'Last day before first day', steps: 'from +10 to +9', expected: 'The last day is before the first day' }, () => { const e = L({ to: plusDays(9) }); return { actual: e, pass: /before the first/.test(e) }; });
  V({ id: 'SELF_LEAVE-03', module: 'My Space', menu: 'My Leave', feature: 'Apply leave', role: 'Teacher', type: 'Negative', category: 'Mandatory field', title: 'Reason of 2 characters', steps: 'Reason "ok"', expected: 'Give a short reason' }, () => { const e = L({ reason: 'ok' }); return { actual: e, pass: /reason/.test(e) }; });
  V({ id: 'SELF_LEAVE-04', module: 'My Space', menu: 'My Leave', feature: 'Apply leave', role: 'Teacher', type: 'Negative', category: 'Business rule', title: 'Casual leave applied after the day', steps: 'CL yesterday', expected: 'Only sick leave can be applied after the day' }, () => { const e = L({ from: plusDays(-1), to: plusDays(-1) }); return { actual: e, pass: /sick/.test(e) }; });
  V({ id: 'SELF_LEAVE-05', module: 'My Space', menu: 'My Leave', feature: 'Apply leave', role: 'Teacher', type: 'Negative', category: 'Dropdown', title: 'Unknown leave type', steps: 'Type "XX"', expected: 'Choose a leave type' }, () => { const e = L({ type: 'XX' }); return { actual: e, pass: /leave type/.test(e) }; });
  V({ id: 'SELF_LEAVE-06', module: 'My Space', menu: 'My Leave', feature: 'Apply leave', role: 'Teacher', type: 'Negative', category: 'Duplicate', title: 'Overlapping leave', steps: 'Apply the same day twice', expected: 'Overlaps your … leave' }, () => { const dd = db0(); const s = dd.staff.find((x) => x.id === st.id); const f = { type: 'CL', from: plusDays(12), to: plusDays(12), reason: 'Family function' }; let e = LV.checkLeave(dd, s, f); if (e) { f.from = f.to = plusDays(13); e = LV.checkLeave(dd, s, f); } if (e) { f.from = f.to = plusDays(14); } LV.applyLeave(dd, s, f, null); const e2 = LV.checkLeave(dd, s, f); return { actual: e2 || 'Accepted', pass: /Overlaps/.test(e2) }; });
  V({ id: 'STF_LEAVE-01', module: 'Staff', menu: 'Leave Requests', feature: 'Decline leave', role: 'Principal', type: 'Negative', category: 'Mandatory field', title: 'Decline without a reason', steps: 'Decline, note blank', expected: 'Give a reason for declining' }, () => { const dd = db0(); const r = dd.staffLeaves.find((x) => x.status === 'PENDING'); const ap = dd.users.find((u) => r.approvers.includes(u.id)); try { LV.decideLeave(dd, r.id, 'DECLINED', ap, ''); return { actual: 'Accepted', pass: false }; } catch (e) { return { actual: 'Refused: ' + e.message, pass: /reason/.test(e.message) }; } });
  V({ id: 'STF_LEAVE-02', module: 'Staff', menu: 'Leave Requests', feature: 'Approve leave', role: 'Accountant', type: 'Negative', category: 'Action not permitted for role', title: 'Someone who is not an approver approves', steps: 'Accountant approves a teacher\'s leave', expected: 'You are not an approver for this request' }, () => { const dd = db0(); const r = dd.staffLeaves.find((x) => x.status === 'PENDING'); const ac = dd.users.find((u) => u.role === 'ACCOUNTANT'); try { LV.decideLeave(dd, r.id, 'APPROVED', ac); return { actual: 'Approved', pass: false }; } catch (e) { return { actual: 'Refused: ' + e.message, pass: /not an approver/.test(e.message) }; } });
