  const C1 = (o) => () => PK.addCollector(d, { studentId: kid.id, name: 'Uncle Raju', relation: 'Uncle', mobile: '9845012777', photo: 'data:image/png;base64,AA', idLast4: '1234', ...o }, 'QA');
  V({ id: 'SELF_REQ-PICKUP-01', module: 'My Space', menu: 'Requests to School › Approved pickup list', feature: 'Add pickup person', role: 'Parent', type: 'Positive', category: 'Add/Save/Retrieve', title: 'Add a pickup person with photo and last 4 of ID', steps: 'Valid person', expected: 'Saved, waiting for the school to check' }, accepts(C1({}), (x) => !!x));
  V({ id: 'SELF_REQ-PICKUP-02', module: 'My Space', menu: 'Requests to School › Approved pickup list', feature: 'Add pickup person', role: 'Parent', type: 'Negative', category: 'Duplicate', title: 'Same mobile twice', steps: 'Add the same person again', expected: 'This person is already on the list' }, refuses(C1({}), /already/));
  V({ id: 'SELF_REQ-PICKUP-03', module: 'My Space', menu: 'Requests to School › Approved pickup list', feature: 'Add pickup person', role: 'Parent', type: 'Negative', category: 'Wrong format', title: 'Last 4 of ID "12a4" and full 12-digit Aadhaar', steps: '12a4, then 123412341234', expected: 'Only the last 4 digits are accepted (never the full ID)' }, () => { const r = ['12a4', '123412341234'].map((v) => { try { C1({ mobile: '98450' + Math.floor(10000 + Math.random() * 89999), idLast4: v })(); return 'accepted'; } catch (e) { return 'refused'; } }); return { actual: r.join(', '), pass: r.every((x) => x === 'refused') }; });
  V({ id: 'SELF_REQ-PICKUP-04', module: 'My Space', menu: 'Requests to School › Approved pickup list', feature: 'Add pickup person', role: 'Parent', type: 'Negative', category: 'Wrong format', title: 'Mobile with +91 and spaces is refused instead of corrected', steps: 'Mobile "+91 98450 12888"', expected: 'Auto-corrected to 9845012888 (shown before saving) — today it is refused' }, () => { try { C1({ mobile: '+91 98450 12888' })(); return { actual: 'Accepted', pass: true }; } catch (e) { return { actual: 'Refused: ' + e.message + ' (candidate for safe auto-correction)', pass: false }; } });
  const rq = (o) => () => PK.submitRequest(d, { studentId: kid.id, type: 'LEAVE', dateFrom: plusDays(3), dateTo: plusDays(4), reason: 'Wedding', ...o }, parent);
  V({ id: 'SELF_REQ-01', module: 'My Space', menu: 'Requests to School', feature: 'Leave request for child', role: 'Parent', type: 'Positive', category: 'Add/Save/Retrieve', title: 'Ask for 2 days of leave', steps: 'Leave, +3 to +4, reason', expected: 'Submitted to the class coordinator' }, accepts(rq({}), (x) => x.status === 'Submitted'));
  V({ id: 'SELF_REQ-02', module: 'My Space', menu: 'Requests to School', feature: 'Leave request for child', role: 'Parent', type: 'Negative', category: 'Duplicate', title: 'Same leave dates again', steps: 'Submit the same request', expected: 'Already asked' }, refuses(rq({}), /already/i));
  V({ id: 'SELF_REQ-03', module: 'My Space', menu: 'Requests to School', feature: 'Leave request for child', role: 'Parent', type: 'Negative', category: 'Boundary', title: 'Leave longer than 30 school days', steps: '+3 to +60', expected: 'Needs a letter to the Principal' }, refuses(rq({ dateFrom: plusDays(5), dateTo: plusDays(70), reason: 'Travel' }), /30 days/));
  V({ id: 'SELF_REQ-04', module: 'My Space', menu: 'Requests to School', feature: 'Early pick-up', role: 'Parent', type: 'Negative', category: 'Boundary', title: 'Early pick-up after dismissal time', steps: 'Time 16:30', expected: 'Early leave time must be before dismissal' }, refuses(rq({ type: 'EARLY_LEAVE', dateTo: '', time: '16:30', reason: 'Doctor' }), /before/));
  V({ id: 'SELF_REQ-05', module: 'My Space', menu: 'Requests to School', feature: 'Leave request for child', role: 'Parent', type: 'Negative', category: 'Restricted data', title: "Parent asks for leave for another family's child", steps: 'studentId of a child not theirs', expected: 'Refused' }, refuses(() => PK.submitRequest(d, { studentId: d.students.find((s) => !parent.children.includes(s.admNo)).id, type: 'LEAVE', dateFrom: plusDays(3), dateTo: plusDays(3), reason: 'X' }, parent)));
